function endfieldChromeHtml() {
  return [
    endfieldOperatorBackgroundHtml(),
    ENDFIELD_SIDEBAR_HTML,
    ENDFIELD_HEADER_DECO_HTML,
    endfieldNoticeDateHtml(formatNoticeDate()),
    endfieldCornerGameplayDecoHtml()
  ].join("");
}

function endfieldOperatorBackgroundHtml() {
  return `
  <div class="endfield-operator-bg" aria-hidden="true">
    <div class="endfield-operator-bg-stage">
      <div class="endfield-bg-deco">
        <div class="endfield-bg-shallow"></div>
        <div class="endfield-bg-flag"></div>
        <div class="endfield-bg-hollow">ENDFIELD</div>
        <div class="endfield-bg-tape">
          <div class="endfield-bg-color-line"></div>
        </div>
        <div class="endfield-bg-deco-line">${ENDFIELD_BACKGROUND_LINE_SVG}</div>
        <div class="endfield-bg-plus">${ENDFIELD_BACKGROUND_PLUS_SVG}</div>
      </div>
    </div>
  </div>
`;
}

function endfieldNoticeDateHtml(dateLabel) {
  return `
  <div class="endfield-notice-date" aria-hidden="true">
    <div class="__06-Notice_wrapper__g1OkM"></div>
    <div class="__06-Notice_textWrapper__nvUA3">
      <div class="__06-Notice_latest__ySg6h">${dateLabel}</div>
      <div class="__06-Notice_divider__1U63x"></div>
    </div>
  </div>
`;
}

function endfieldCornerGameplayDecoHtml() {
  return `
  <div class="endfield-corner-gameplay-deco" aria-hidden="true">
    ${ENDFIELD_CORNER_GAMEPLAY_DECO_SVG}
  </div>
`;
}

export function applyEndfieldTemplate(root) {
  if (!root) {
    return;
  }

  insertTemplateChrome(root);

  if (!canTransformDom(root)) {
    return;
  }

  transformProfileHeading(root);
  transformProfileContacts(root);
  transformSectionHeadings(root);
}

function insertTemplateChrome(root) {
  if (typeof root.querySelector === "function" && root.querySelector(".endfield-operator-bg")) {
    return;
  }

  if (typeof root.insertAdjacentHTML === "function") {
    root.insertAdjacentHTML("afterbegin", endfieldChromeHtml());
    return;
  }

  if ("innerHTML" in root) {
    root.innerHTML = `${endfieldChromeHtml()}${root.innerHTML}`;
  }
}

function canTransformDom(root) {
  return typeof root.querySelector === "function" && typeof root.querySelectorAll === "function" && Boolean(globalThis.document?.createElement);
}

function transformProfileHeading(root) {
  const profile = root.querySelector(".resume-profile");
  const heading = profile?.querySelector("h1");

  if (!profile || !heading || profile.querySelector(".endfield-profile-heading")) {
    return;
  }

  const container = document.createElement("div");
  const inner = document.createElement("div");
  const icons = document.createElement("div");
  const nameContainer = document.createElement("div");
  const leftBracket = document.createElement("span");
  const rightBracket = document.createElement("span");
  const assaultIcon = document.createElement("div");
  const electricIcon = document.createElement("div");

  container.className = "endfield-profile-heading __02-Operator_titleContainer__6rOf9";
  inner.className = "__02-Operator_titleInnerContainer__1rOJW";
  icons.className = "__02-Operator_icons__Ntn1x";
  nameContainer.className = "__02-Operator_nameContainer__yjlQE";
  leftBracket.className = "__02-Operator_leftBracket__MSSfG";
  rightBracket.className = "__02-Operator_rightBracket__YpY2O";
  heading.className = "__02-Operator_title__Qc2kT";
  assaultIcon.className = "__02-Operator_icon__GnwPC";
  electricIcon.className = "__02-Operator_icon__GnwPC";
  assaultIcon.dataset.key = "assault";
  electricIcon.dataset.key = "electric";
  leftBracket.textContent = "[";
  rightBracket.textContent = "]";

  icons.append(assaultIcon, electricIcon);
  nameContainer.append(leftBracket, heading, rightBracket);
  inner.append(icons, nameContainer);
  container.append(inner);
  profile.prepend(container);
}

function transformProfileContacts(root) {
  const contacts = root.querySelector(".resume-contacts");

  if (!contacts || contacts.parentElement?.querySelector(".endfield-profile-tags")) {
    return;
  }

  const tagList = document.createElement("div");
  const tags = Array.from(contacts.querySelectorAll(".contact"), createProfileTag);

  tagList.className = "endfield-profile-tags";

  for (const [index, rowTags] of groupProfileTags(tags).entries()) {
    tagList.append(createProfileTagRow(rowTags, index));
  }

  contacts.replaceWith(tagList);
}

function transformSectionHeadings(root) {
  for (const heading of root.querySelectorAll(".resume-section > h2")) {
    if (heading.querySelector(".endfield-section-title-row")) {
      continue;
    }

    const title = heading.textContent.trim();
    const pre = document.createElement("span");
    const titleRow = document.createElement("span");
    const icon = document.createElement("span");
    const titleText = document.createElement("span");

    pre.className = "__05-Gameplay_endfieldPre__LUcJv";
    titleRow.className = "endfield-section-title-row";
    icon.className = "endfield-section-title-icon";
    titleText.className = "endfield-section-title-text";
    icon.setAttribute("aria-hidden", "true");
    pre.innerHTML = ENDFIELD_SECTION_PRE_SVG;
    icon.innerHTML = SECTION_ARROW_SVG;
    titleText.textContent = title;

    titleRow.append(icon, titleText);
    heading.replaceChildren(pre, titleRow);
  }
}

function splitContact(contact) {
  const text = contact.textContent ?? "";
  const separatorIndex = text.indexOf("：");

  if (separatorIndex === -1) {
    return {
      label: "",
      value: text.trim(),
      valueNode: document.createTextNode(text.trim())
    };
  }

  const label = text.slice(0, separatorIndex).trim();
  const value = text.slice(separatorIndex + 1).trim();
  const link = contact.querySelector("a");

  if (link) {
    return {
      label,
      value,
      valueNode: link.cloneNode(true)
    };
  }

  return {
    label,
    value,
    valueNode: document.createTextNode(value)
  };
}

function createProfileTag(contact) {
  const { label, value, valueNode } = splitContact(contact);
  const tag = document.createElement("div");
  const labelEl = document.createElement("div");
  const valueEl = document.createElement("div");

  tag.className = "__02-Operator_tag__FQrt0";
  labelEl.className = "__02-Operator_label__3koYX";
  valueEl.className = "__02-Operator_value__w_bbs";
  labelEl.textContent = label;
  valueEl.append(valueNode);
  tag.append(labelEl, valueEl);
  tag.dataset.profileWeight = String(estimateProfileTagWeight(label, value));
  return tag;
}

function createProfileTagRow(tags, index) {
  const row = document.createElement("div");

  row.className = "__02-Operator_tagContainer__dKENE";

  if (index % 2 === 1) {
    row.classList.add("is-yellow");
  }

  row.append(...tags);
  return row;
}

function groupProfileTags(tags) {
  const rows = [];
  let currentRow = [];
  let currentWeight = 0;
  const maxRowWeight = 96;

  for (const tag of tags) {
    const weight = Number(tag.dataset.profileWeight) || 0;
    const shouldWrap = currentRow.length > 0 && currentWeight + weight > maxRowWeight;

    if (shouldWrap) {
      rows.push(currentRow);
      currentRow = [];
      currentWeight = 0;
    }

    currentRow.push(tag);
    currentWeight += weight;
  }

  if (currentRow.length > 0) {
    rows.push(currentRow);
  }

  return rows;
}

function estimateProfileTagWeight(label, value) {
  return getTextWeight(label) + getTextWeight(value) + 8;
}

function getTextWeight(text) {
  return Array.from(String(text ?? "")).reduce((weight, char) => {
    return weight + (/[\u3400-\u9fff]/u.test(char) ? 2 : 1);
  }, 0);
}

function formatNoticeDate(date = new Date()) {
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");

  return `${month}${day}`;
}
